<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('hr');$rows=$pdo->query('SELECT l.*,d.nama_divisi FROM lowongan l JOIN divisi d ON d.id_divisi=l.id_divisi ORDER BY l.id_lowongan DESC')->fetchAll();page_header('Pengajuan Lowongan');?><table><tr><th>Posisi</th><th>Divisi</th><th>Kebutuhan</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['judul_lowongan'])?></td><td><?=e($r['nama_divisi'])?></td><td><?=e($r['jumlah_kebutuhan'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Diajukan'):?><form method="post" action="proses_pengajuan.php" class="actions"><input type="hidden" name="id" value="<?=$r['id_lowongan']?>"><button class="btn success" name="aksi" value="setujui">Terima</button><button class="btn danger" name="aksi" value="tolak">Tolak</button></form><?php elseif($r['status']==='Disetujui'):?><a class="btn" href="buat_lowongan.php?id=<?=$r['id_lowongan']?>">Lengkapi & Publish</a><?php endif;?></td></tr><?php endforeach;?></table><?php page_footer();
